{
  "classification": "exploratory",
  "sql": "WITH first_listed AS (SELECT listing_id, MIN(snapshot_date) AS listed_date FROM marts.fct_listings WHERE is_active GROUP BY listing_id), first_sale AS (SELECT listing_id, MIN(CAST(paid_at AS DATE)) AS sold_date FROM marts.fct_orders WHERE is_paid AND NOT paid_at IS NULL GROUP BY listing_id) SELECT COUNT(*) AS listings_sold, AVG(DATE_DIFF('DAY', l.listed_date, s.sold_date)) AS avg_days_to_sell, MEDIAN(DATE_DIFF('DAY', l.listed_date, s.sold_date)) AS median_days_to_sell FROM first_listed AS l JOIN first_sale AS s USING (listing_id) WHERE s.sold_date >= l.listed_date",
  "columns": [
    "listings_sold",
    "avg_days_to_sell",
    "median_days_to_sell"
